<?php
declare(strict_types=1);
require __DIR__ . '/app/auth.php';
exigirEquipe();
require __DIR__ . '/app/db.php';

$id = (int) ($_GET['id'] ?? 0);
$consulta = banco()->prepare('SELECT o.*, c.nome, c.telefone FROM orcamentos o JOIN clientes c ON c.id = o.cliente_id WHERE o.id = ?');
$consulta->execute([$id]);
$orcamento = $consulta->fetch();
if (!$orcamento || !in_array($orcamento['status'], ['rascunho', 'pronto_para_envio'], true)) { http_response_code(404); exit('Apenas rascunhos ou orçamentos prontos para envio podem ser editados.'); }
$consulta = banco()->prepare('SELECT * FROM itens_orcamento WHERE orcamento_id = ? ORDER BY id');
$consulta->execute([$id]);
$itens = $consulta->fetchAll();
$catalogo = require __DIR__ . '/app/catalogo-inicial.php';
function esc(string $texto): string { return htmlspecialchars($texto, ENT_QUOTES, 'UTF-8'); }
function telefoneExibicao(string $telefone): string { $numero = preg_replace('/\D+/', '', $telefone); return preg_match('/^55(\d{2})(\d{4,5})(\d{4})$/', $numero, $partes) ? '+55 (' . $partes[1] . ') ' . $partes[2] . '-' . $partes[3] : $telefone; }
function valorInicial(array $item): int { return (int) ($item['valor_centavos'] ?? $item['valor_minimo_centavos'] ?? 0); }
function grupoServico(string $nome): string
{
    $texto = mb_strtolower($nome, 'UTF-8');
    if (str_contains($texto, 'solda')) return 'solda';
    if (str_contains($texto, 'piso') || str_contains($texto, 'porcelanato') || str_contains($texto, 'azulejo') || str_contains($texto, 'revestimento') || str_contains($texto, 'rejuntamento') || str_contains($texto, 'rodapé') || str_contains($texto, 'soleira') || str_contains($texto, 'peitoril')) return 'pisos';
    if (str_contains($texto, 'chapisco') || str_contains($texto, 'emboço') || str_contains($texto, 'reboco')) return 'reboco';
    if (str_contains($texto, 'demolição') || str_contains($texto, 'retirada') || str_contains($texto, 'abertura')) return 'demolicao';
    if (str_contains($texto, 'porta') || str_contains($texto, 'marco') || str_contains($texto, 'churrasqueira') || str_contains($texto, 'forno') || str_contains($texto, 'bancada') || str_contains($texto, 'nicho') || str_contains($texto, 'rasgos') || str_contains($texto, 'reparos') || str_contains($texto, 'telhado') || str_contains($texto, 'oitão') || str_contains($texto, 'impermeabilização')) return 'acabamento';
    return 'base';
}
function valorExibicao(array $item): string {
    if (isset($item['valor_minimo_centavos'], $item['valor_maximo_centavos'])) return 'R$ ' . number_format($item['valor_minimo_centavos'] / 100, 2, ',', '.') . '–' . number_format($item['valor_maximo_centavos'] / 100, 2, ',', '.');
    return 'R$ ' . number_format(valorInicial($item) / 100, 2, ',', '.');
}
$dadosIniciais = ['id' => $id, 'itens' => array_map(static function (array $item): array {
    $tipo = $item['periodo_tipo'];
    return ['id' => (int) $item['id'], 'name' => $item['descricao'], 'category' => $item['categoria'] === 'mao_de_obra' ? 'Mão de obra' : 'Equipamentos locados', 'unit' => $item['unidade'], 'rateType' => $tipo, 'rateLabel' => $tipo === 'diaria' ? 'Diária' : ($tipo === 'mensal' ? 'Mensal' : ($tipo === 'peca' ? 'Por peça' : null)), 'quantity' => (float) $item['quantidade'], 'period' => $item['periodo_quantidade'] === null ? null : (float) $item['periodo_quantidade'], 'tableValue' => (int) ($item['valor_tabela_centavos'] ?? $item['valor_unitario_centavos']), 'value' => (int) $item['valor_unitario_centavos']];
}, $itens)];
?>
